#include <iostream>
#include <string>
template <class T>
void printConstRef(const T& value) {
    std::cout << value << std::endl;  // Uses the const reference without copying
}
int main() {
    std::string str = "Hello, C++!";
    printConstRef(str);  // Instantiates for T = std::string
    int num = 42;
    printConstRef(num);   // Instantiates for T = int
    return 0;
}
